local function trigger(ctx,self,event)return event.player==ctx:controller(self)end
local function upgrade(ctx,self)local id=ctx:entity(self).card_id;if id=="LOOT_203"then ctx:attach_script(self,"LOOT_203");ctx:transform_preserving_scripts(self,"LOOT_203t2")elseif id=="LOOT_203t2"then ctx:transform_preserving_scripts(self,"LOOT_203t3")end end
local triggers={{event="weapon_equipped",timing="after",active_zones={"hand"},condition=trigger,effect=upgrade}}
local function cast(n)return function(ctx,self)for _=1,n do ctx:summon(ctx:controller(self),"LOOT_203t4")end end end
return {api_version=1,id="LOOT_203",name="Lesser Mithril Spellstone",text="Summon one 5/5 Mithril Golem. <i>(Equip a weapon to upgrade.)</i>",set="LOOTAPALOOZA",type="spell",class="warrior",rarity="rare",cost=7,triggers=triggers,on_play=cast(1),tokens={{id="LOOT_203t2",name="Mithril Spellstone",text="Summon two 5/5 Mithril Golems. <i>(Equip a weapon to upgrade.)</i>",set="LOOTAPALOOZA",type="spell",class="warrior",cost=7,on_play=cast(2)},{id="LOOT_203t3",name="Greater Mithril Spellstone",text="Summon three 5/5 Mithril Golems.",set="LOOTAPALOOZA",type="spell",class="warrior",cost=7,on_play=cast(3)},{id="LOOT_203t4",name="Mithril Golem",text="",set="LOOTAPALOOZA",type="minion",class="warrior",cost=5,attack=5,health=5}}}
